  ('kasavu', 'Kerala Kasavu', '{"id":"kasavu","name":"Kerala Kasavu","description":"Gold kasavu borders and brass nilavilakku lamps, jasmine, and Raag Madhyamavati.","occasion":"wedding","scene":{"format":"gate-fold","motif":"kasavu","petals":{"colours":["petal-jasmine","marigold","petal-jasmine"],"size":0.8},"lanterns":false},"colours":{"paper":"tpl-kasavu-paper","ink":"tpl-kasavu-ink","inkMuted":"tpl-kasavu-ink","gold":"tpl-kasavu-ornament","goldText":"tpl-kasavu-accent","accent":"tpl-kasavu-kumkum","accentText":"tpl-kasavu-accent","back":"tpl-kasavu-back"},"fonts":{"names":{"font":"display","italic":false,"uppercase":false,"tracking":0,"scale":1},"labels":{"font":"label","italic":false,"uppercase":true,"tracking":0.3,"scale":1},"body":{"font":"sans","italic":true,"uppercase":false,"tracking":0,"scale":1}},"music":{"raga":"madhyamavati"},"slots":[{"id":"doorLeft","sample":"Shubha"},{"id":"doorRight","sample":"Muhurtham"},{"id":"blessing","sample":""},{"id":"families","sample":"The Nair and Menon families"},{"id":"first","sample":"Arjun"},{"id":"joiner","sample":"&"},{"id":"second","sample":"Lakshmi"},{"id":"line","sample":"invite you to bless them on their wedding day"},{"id":"date","sample":"Sunday, 17 January 2027 · 10.30 am"},{"id":"venue","sample":"Sree Krishna Auditorium, Guruvayur"}]}'::jsonb, 5)
